      "id": "T1",
      "title": "Regularized Logistic Regression for Tabular Classification",
      "bullets": [
        "Implemented a scikit-learn baseline with missing value imputation, feature standardization, and regularized logistic regression for a tabular classification task.",
        "Compared regularization settings through cross-validation on training data and summarized held-out predictions using confusion matrices and probability-based evaluation metrics."
      ]
    }
  ]
